mapper.select:
select
sum(Fs_Money)
from Pro_Inv_Detail mn
left join Pre_Project pro on pro.P_Id = mn.P_Id
left join SYS_Department prod on prod.D_Id=pro.P_Competent_Department
where pro.state = 7 and pro.deleted = false

    and pro.Te_Id=#{params.teId}


    and pro.P_Construction_Unit=#{params.cId}


    and mn.P_Id=#{params.pId}


    and pro.P_Type=#{params.pType}


    and INSTR(pro.P_Name,#{params.pName})


    and INSTR(prod.D_Name,#{params.pCompetentDepartment})

and mn.P_Id in (
select P_Id from Oa_Annual_Plan_Dtl apd
left join Oa_Annual_Plan ap on ap.id=apd.Ap_Id
where ap.Ap_Year=#{params.year}
)

select p_Id as "pId", sum(Fs_Money) as "fsMoney" from Pro_Inv_Detail where P_Id in
#{item}
group by P_Id
